 36 | 
 37 |         int yearMagnitude = ParseDigits(value, ref cursor, yearDigits, "year");
 38 |         int year = checked(yearSign * yearMagnitude);
 39 | 
 40 |         ExpectCharacter(value, ref cursor, '-');
 41 |         int month = ParseDigits(value, ref cursor, 2, "month");
 42 |         ExpectCharacter(value, ref cursor, '-');
 43 |         int day = ParseDigits(value, ref cursor, 2, "day");
 44 | 
 45 |         ValidateDate(year, month, day);
 46 | 
 47 |         if (cursor == value.Length)
 48 |         {
 49 |             return CreateFromParts(year, month, day, 0, 0, 0, 0, 0);
 50 |         }
 51 | 
 52 |         ExpectCharacter(value, ref cursor, 'T');
 53 |         int hour = ParseDigits(value, ref cursor, 2, "hour");
 54 |         ExpectCharacter(value, ref cursor, ':');
 55 |         int minute = ParseDigits(value, ref cursor, 2, "minute");
 56 |         ExpectCharacter(value, ref cursor, ':');
 57 |         int second = ParseDigits(value, ref cursor, 2, "second");
 58 | 
 59 |         if (hour > 23)
 60 |         {
 61 |             throw new FormatException("Hour is greater than 23.");
 62 |         }
 63 | 
 64 |         if (minute > 59)
 65 |         {
 66 |             throw new FormatException("Minute is greater than 59.");
 67 |         }
 68 | 
 69 |         if (second > 59)
 70 |         {
 71 |             throw new FormatException("Second is greater than 59.");
 72 |         }
 73 | 
 74 |         int milliseconds = 0;
 75 | 
 76 |         if (cursor < value.Length && value[cursor] == '.')
 77 |         {
 78 |             cursor++;
 79 |             milliseconds = ParseDigits(value, ref cursor, 3, "millisecond");
 80 |         }
 81 | 
 82 |         if (cursor == value.Length)
 83 |         {
 84 |             throw new FormatException("Datetime values must include a time zone designator.");
 85 |         }
 86 | 
 87 |         long offsetMilliseconds = value[cursor] switch
 88 |         {
 89 |             'Z' => ReadUtcTrailer(value, ref cursor),
 90 |             '+' => ReadOffset(value, ref cursor, 1),
 91 |             '-' => ReadOffset(value, ref cursor, -1),
 92 |             _ => throw new FormatException("Invalid time zone designator.")
 93 |         };
 94 | 
 95 |         if (cursor != value.Length)
 96 |         {
 97 |             throw new FormatException("Unexpected trailing characters after the time zone designator.");
 98 |         }
 99 | 
100 |         return CreateFromParts(year, month, day, hour, minute, second, milliseconds, offsetMilliseconds);
101 |     }
