133 |     private static CedarDatetime CreateFromParts(int year, int month, int day, int hour, int minute, int second, int millisecond, long offsetMilliseconds)
134 |     {
135 |         GregorianDateTimeParts utcParts = NormalizeUtcParts(year, month, day, hour, minute, second, millisecond, offsetMilliseconds);
136 |         if (CompareParts(utcParts, MinSupportedInstant) < 0 || CompareParts(utcParts, MaxSupportedInstant) > 0)
137 |         {
138 |             throw new FormatException("Timestamp is out of range.");
139 |         }
140 | 
141 |         // Compute entirely in Int128 so that boundary dates with timezone offsets
142 |         // are handled correctly. The offset must be applied before range-checking,
143 |         // otherwise a pre-offset value that exceeds long range would be rejected
144 |         // even if the final UTC result fits (e.g. +292278994-08-17T08:12:55.807+0100).
145 |         long days = GregorianDateTime.DaysFromCivil(year, month, day);
146 |         Int128 totalMs =
147 |             (Int128)days * CedarConsts.MillisPerDay
148 |             + hour * (long)CedarConsts.MillisPerHour
149 |             + minute * (long)CedarConsts.MillisPerMinute
150 |             + second * (long)CedarConsts.MillisPerSecond
151 |             + millisecond
152 |             - offsetMilliseconds;
153 | 
154 |         if (totalMs < long.MinValue || totalMs > long.MaxValue)
155 |         {
156 |             throw new FormatException("Timestamp is out of range.");
157 |         }
158 | 
159 |         return new CedarDatetime((long)totalMs);
160 |     }
161 | 
162 |     private static string FormatYear(int year)
163 |     {
164 |         if (year is >= 0 and <= 9999)
165 |         {
166 |             return year.ToString("D4", CultureInfo.InvariantCulture);
167 |         }
168 | 
169 |         long absoluteYear = year < 0 ? -(long)year : year;
170 |         string sign = year < 0 ? "-" : "+";
171 |         return sign + absoluteYear.ToString("D9", CultureInfo.InvariantCulture);
172 |     }
173 | 
174 |     private static GregorianDateTimeParts NormalizeUtcParts(int year, int month, int day, int hour, int minute, int second, int millisecond, long offsetMilliseconds)
175 |     {
176 |         long timeOfDayMilliseconds =
177 |             (hour * (long)CedarConsts.MillisPerHour)
178 |             + (minute * (long)CedarConsts.MillisPerMinute)
179 |             + (second * (long)CedarConsts.MillisPerSecond)
180 |             + millisecond
181 |             - offsetMilliseconds;
182 | 
183 |         int dayAdjustment = 0;
184 |         if (timeOfDayMilliseconds < 0)
185 |         {
186 |             dayAdjustment = -1;
187 |             timeOfDayMilliseconds += CedarConsts.MillisPerDay;
188 |         }
189 |         else if (timeOfDayMilliseconds >= CedarConsts.MillisPerDay)
190 |         {
191 |             dayAdjustment = 1;
192 |             timeOfDayMilliseconds -= CedarConsts.MillisPerDay;
193 |         }
194 | 
195 |         AdjustCivilDate(ref year, ref month, ref day, dayAdjustment);
196 | 
197 |         int utcHour = (int)(timeOfDayMilliseconds / CedarConsts.MillisPerHour);
198 |         timeOfDayMilliseconds %= CedarConsts.MillisPerHour;
199 | 
200 |         int utcMinute = (int)(timeOfDayMilliseconds / CedarConsts.MillisPerMinute);
201 |         timeOfDayMilliseconds %= CedarConsts.MillisPerMinute;
202 | 
203 |         int utcSecond = (int)(timeOfDayMilliseconds / CedarConsts.MillisPerSecond);
204 |         int utcMillisecond = (int)(timeOfDayMilliseconds % CedarConsts.MillisPerSecond);
205 | 
206 |         return new GregorianDateTimeParts(year, month, day, utcHour, utcMinute, utcSecond, utcMillisecond);
207 |     }
208 | 
209 |     private static void AdjustCivilDate(ref int year, ref int month, ref int day, int dayAdjustment)
210 |     {
211 |         if (dayAdjustment == 0)
212 |         {
213 |             return;
214 |         }
215 | 
216 |         if (dayAdjustment > 0)
217 |         {
218 |             day++;
219 |             int daysInMonth = GregorianDateTime.DaysInMonth(year, month);
220 |             if (day > daysInMonth)
221 |             {
222 |                 day = 1;
223 |                 month++;
224 |                 if (month > 12)
225 |                 {
226 |                     month = 1;
227 |                     year = checked(year + 1);
228 |                 }
229 |             }
230 | 
231 |             return;
232 |         }
233 | 
234 |         day--;
235 |         if (day > 0)
236 |         {
237 |             return;
238 |         }
239 | 
240 |         month--;
241 |         if (month < 1)
242 |         {
243 |             month = 12;
244 |             year = checked(year - 1);
245 |         }
246 | 
247 |         day = GregorianDateTime.DaysInMonth(year, month);
248 |     }
249 | 
250 |     private static int CompareParts(GregorianDateTimeParts left, GregorianDateTimeParts right)
251 |     {
252 |         int comparison = left.Year.CompareTo(right.Year);
253 |         if (comparison != 0)
254 |         {
255 |             return comparison;
256 |         }
257 | 
258 |         comparison = left.Month.CompareTo(right.Month);
259 |         if (comparison != 0)
260 |         {
261 |             return comparison;
262 |         }
263 | 
264 |         comparison = left.Day.CompareTo(right.Day);
265 |         if (comparison != 0)
266 |         {
267 |             return comparison;
268 |         }
269 | 
270 |         comparison = left.Hour.CompareTo(right.Hour);
271 |         if (comparison != 0)
272 |         {
273 |             return comparison;
274 |         }
275 | 
276 |         comparison = left.Minute.CompareTo(right.Minute);
277 |         if (comparison != 0)
278 |         {
279 |             return comparison;
280 |         }
281 | 
282 |         comparison = left.Second.CompareTo(right.Second);
283 |         if (comparison != 0)
284 |         {
285 |             return comparison;
286 |         }
287 | 
288 |         return left.Millisecond.CompareTo(right.Millisecond);
289 |     }
290 | 
291 |     private static void ExpectCharacter(string value, ref int cursor, char expected)
292 |     {
293 |         if (value.Length <= cursor || value[cursor] != expected)
294 |         {
295 |             throw new FormatException($"Expected '{expected}' at position {cursor}.");
296 |         }
297 | 
298 |         cursor++;
299 |     }
300 | 
301 |     private static int ParseDigits(string value, ref int cursor, int length, string component)
302 |     {
303 |         if (value.Length < cursor + length)
304 |         {
305 |             throw new FormatException($"Invalid {component} component.");
306 |         }
307 | 
308 |         int parsed = 0;
309 |         for (int index = 0; index < length; index++)
310 |         {
311 |             char character = value[cursor + index];
312 |             if (!char.IsAsciiDigit(character))
313 |             {
314 |                 throw new FormatException($"Invalid {component} component.");
315 |             }
316 | 
317 |             parsed = checked(parsed * 10 + (character - '0'));
318 |         }
319 | 
320 |         cursor += length;
321 |         return parsed;
322 |     }
323 | 
324 |     private static long ReadUtcTrailer(string value, ref int cursor)
325 |     {
326 |         cursor++;
327 |         return 0;
328 |     }
329 | 
330 |     private static long ReadOffset(string value, ref int cursor, int sign)
331 |     {
332 |         cursor++;
333 | 
334 |         if (value.Length != cursor + 4)
335 |         {
336 |             throw new FormatException("Time zone offsets must use the +hhmm or -hhmm form.");
337 |         }
338 | 
339 |         int hours = ParseDigits(value, ref cursor, 2, "time zone hour");
340 |         int minutes = ParseDigits(value, ref cursor, 2, "time zone minute");
341 | 
342 |         if (hours > 23)
343 |         {
344 |             throw new FormatException("Time zone offset hours are greater than 23.");
345 |         }
346 | 
347 |         if (minutes > 59)
348 |         {
349 |             throw new FormatException("Time zone offset minutes are greater than 59.");
350 |         }
351 | 
352 |         long magnitude = (hours * CedarConsts.MillisPerHour) + (minutes * CedarConsts.MillisPerMinute);
353 |         return sign * magnitude;
354 |     }
355 | 
356 |     private static void ValidateDate(int year, int month, int day)
357 |     {
358 |         if (month is < 1 or > 12)
359 |         {
360 |             throw new FormatException("Month is greater than 12.");
361 |         }
362 | 
363 |         if (day is < 1 or > 31)
364 |         {
365 |             throw new FormatException("Day is greater than 31.");
366 |         }
367 | 
368 |         int daysInMonth = GregorianDateTime.DaysInMonth(year, month);
369 |         if (day > daysInMonth)
370 |         {
371 |             throw new FormatException("Date is invalid.");
372 |         }
373 |     }
374 | }

